import{_ as s,c as i,o as e,a3 as t}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Installation & Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"master/installation/installation.md","filePath":"master/installation/installation.md","lastUpdated":1793789124000}'),n={name:"master/installation/installation.md"};function l(o,a,r,h,d,p){return e(),i("div",null,a[0]||(a[0]=[t(`<h1 id="installation-configuration" tabindex="-1">Installation &amp; Configuration <a class="header-anchor" href="#installation-configuration" aria-label="Permalink to &quot;Installation &amp; Configuration&quot;">​</a></h1><p>Installing and setting up AureusERP is quick and straightforward. Follow the steps below to get started:</p><h2 id="_1-clone-or-download-the-repository" tabindex="-1">1. Clone or Download the Repository <a class="header-anchor" href="#_1-clone-or-download-the-repository" aria-label="Permalink to &quot;1. Clone or Download the Repository&quot;">​</a></h2><p>You can get the latest version of AureusERP from GitHub:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/aureuserp/aureuserp.git</span></span></code></pre></div><p>Alternatively, you can download the ZIP file from the repository and extract it.</p><h2 id="_2-navigate-to-the-project-root" tabindex="-1">2. Navigate to the Project Root <a class="header-anchor" href="#_2-navigate-to-the-project-root" aria-label="Permalink to &quot;2. Navigate to the Project Root&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureuserp</span></span></code></pre></div><h2 id="_3-install-php-dependencies" tabindex="-1">3. Install PHP Dependencies <a class="header-anchor" href="#_3-install-php-dependencies" aria-label="Permalink to &quot;3. Install PHP Dependencies&quot;">​</a></h2><p>Run the following command to install the required PHP dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="_4-configure-the-environment-file" tabindex="-1">4. Configure the Environment File <a class="header-anchor" href="#_4-configure-the-environment-file" aria-label="Permalink to &quot;4. Configure the Environment File&quot;">​</a></h2><p>Copy the example environment file and generate the application key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key:generate</span></span></code></pre></div><p>By default, the application uses MySQL (<code>DB_CONNECTION=mysql</code>). Edit the <code>.env</code> file and configure the database settings as per your environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_CONNECTION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mysql</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3306</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_DATABASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_USERNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_user</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_password</span></span></code></pre></div><p>Or, to use MariaDB 10.6+:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_CONNECTION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mariadb</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3306</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_DATABASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_USERNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_user</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_password</span></span></code></pre></div><p>Or, to use PostgreSQL 16+ (supported as of v1.5.0):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_CONNECTION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pgsql</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">5432</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_DATABASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_USERNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_user</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DB_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_database_password</span></span></code></pre></div><h2 id="_5-run-the-installation-command" tabindex="-1">5. Run the Installation Command <a class="header-anchor" href="#_5-run-the-installation-command" aria-label="Permalink to &quot;5. Run the Installation Command&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> erp:install</span></span></code></pre></div><p>The installer asks for:</p><ol><li><strong>Country</strong>: the country your business is based in. The default currency is taken from it.</li><li><strong>Admin name, email and password</strong>: used to log in to the admin panel. The password must be at least 8 characters.</li></ol><h3 id="non-interactive-install" tabindex="-1">Non-interactive install <a class="header-anchor" href="#non-interactive-install" aria-label="Permalink to &quot;Non-interactive install&quot;">​</a></h3><p>To skip all prompts, pass the values as options:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> erp:install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --admin-name=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Administrator&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --admin-email=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin@example.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --admin-password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;password&quot;</span></span></code></pre></div><p>Add <code>--country=&quot;India&quot;</code> or <code>--currency=&quot;INR&quot;</code> to also set the country or currency. If you pass neither, the currency from <code>APP_CURRENCY</code> in <code>.env</code> (default <code>USD</code>) is used.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>If not passed</th></tr></thead><tbody><tr><td><code>--admin-name</code></td><td>Admin user name.</td><td>Asked as a prompt.</td></tr><tr><td><code>--admin-email</code></td><td>Admin user email.</td><td>Asked as a prompt.</td></tr><tr><td><code>--admin-password</code></td><td>Admin password (minimum 8 characters).</td><td>Asked as a prompt.</td></tr><tr><td><code>--country</code></td><td>Country name or two letter code. The currency is derived from it.</td><td>Asked as a prompt.</td></tr><tr><td><code>--currency</code></td><td>Currency ISO code. Overrides the country.</td><td>Currency from <code>APP_CURRENCY</code> in <code>.env</code>.</td></tr><tr><td><code>--force</code></td><td>Skip the reinstall confirmation. The database is wiped.</td><td>Confirmation is asked.</td></tr></tbody></table><h2 id="_6-what-happens-during-installation" tabindex="-1">6. What Happens During Installation? <a class="header-anchor" href="#_6-what-happens-during-installation" aria-label="Permalink to &quot;6. What Happens During Installation?&quot;">​</a></h2><h3 id="a-migrations" tabindex="-1">a. Migrations <a class="header-anchor" href="#a-migrations" aria-label="Permalink to &quot;a. Migrations&quot;">​</a></h3><ul><li>All migrations are executed to set up the database schema.</li></ul><h3 id="b-roles-permissions" tabindex="-1">b. Roles &amp; Permissions <a class="header-anchor" href="#b-roles-permissions" aria-label="Permalink to &quot;b. Roles &amp; Permissions&quot;">​</a></h3><ul><li>The <code>Filament Shield</code> package automatically generates roles and permissions for the application, and all permissions are assigned to the admin role.</li></ul><h3 id="c-storage-link" tabindex="-1">c. Storage Link <a class="header-anchor" href="#c-storage-link" aria-label="Permalink to &quot;c. Storage Link&quot;">​</a></h3><ul><li>A symbolic link from <code>public/storage</code> to <code>storage/app/public</code> is created if it does not already exist.</li></ul><h3 id="d-seeders" tabindex="-1">d. Seeders <a class="header-anchor" href="#d-seeders" aria-label="Permalink to &quot;d. Seeders&quot;">​</a></h3><ul><li>Seeders are executed to populate initial data, including the default company. The country and currency from step 5 are then applied to that company.</li></ul><h3 id="e-admin-user-default-settings" tabindex="-1">e. Admin User &amp; Default Settings <a class="header-anchor" href="#e-admin-user-default-settings" aria-label="Permalink to &quot;e. Admin User &amp; Default Settings&quot;">​</a></h3><ul><li>The admin user is created, assigned the admin role, and linked to the default company, and the default settings (company, role, and currency) are synced.</li></ul><h3 id="f-installation-marker" tabindex="-1">f. Installation Marker <a class="header-anchor" href="#f-installation-marker" aria-label="Permalink to &quot;f. Installation Marker&quot;">​</a></h3><ul><li>A <code>storage/installed</code> file is created to mark the installation as complete.</li></ul><div class="tip custom-block"><p class="custom-block-title">APP_CURRENCY</p><p>The base currency is stored in the settings. If it differs from <code>APP_CURRENCY</code> in your <code>.env</code>, the installer prints a warning. Set <code>APP_CURRENCY</code> to the installed currency so the fallback matches.</p></div><h2 id="_7-admin-account-setup" tabindex="-1">7. Admin Account Setup <a class="header-anchor" href="#_7-admin-account-setup" aria-label="Permalink to &quot;7. Admin Account Setup&quot;">​</a></h2><p>During the installation, you will be prompted to provide <strong>Admin Login Credentials</strong> (name, email, and password). These credentials are used to log in to the admin panel. The password must be at least 8 characters long.</p><div class="warning custom-block"><p class="custom-block-title">Reinstallation</p><p>If AureusERP is already installed (the <code>storage/installed</code> file exists), running <code>php artisan erp:install</code> again asks you to type <code>REINSTALL</code> and then confirm a second time. It then runs <code>migrate:fresh</code> and <strong>wipes the database</strong> before reinstalling. This action cannot be undone. Passing <code>--force</code> skips these confirmations.</p></div><h2 id="_8-filament-installation-notes" tabindex="-1">8. Filament Installation Notes <a class="header-anchor" href="#_8-filament-installation-notes" aria-label="Permalink to &quot;8. Filament Installation Notes&quot;">​</a></h2><ul><li>AureusERP uses FilamentPHP, which introduces new features and improvements.</li><li>Ensure your PHP version is compatible (PHP 8.3 or higher required).</li><li>The installation process automatically sets up Filament Shield roles and permissions.</li><li>Filament resources, pages, clusters, and widgets are registered separately for admin and customer panels.</li><li>For plugin development, follow the new Filament resource registration structure.</li><li>The <code>composer.json</code> includes a post-autoload-dump script that runs <code>php artisan filament:upgrade</code> to handle Filament upgrades.</li><li>Refer to the <a href="https://filamentphp.com/docs/5.x" target="_blank" rel="noreferrer">FilamentPHP documentation</a> for detailed information.</li></ul><h2 id="_9-final-steps" tabindex="-1">9. Final Steps <a class="header-anchor" href="#_9-final-steps" aria-label="Permalink to &quot;9. Final Steps&quot;">​</a></h2><p>Once the installation is complete, you can start the development server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Then, open your browser and access the application at:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">http://127.0.0.1:8000</span></span></code></pre></div><p>That’s it! Your AureusERP environment is now ready to use.</p>`,54)]))}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
